<script setup>
import {ref,onMounted,computed} from 'vue'
import {request} from './client'
import PaymentPeriod from './PaymentPeriod.vue'
import {monthWindow} from './paymentDates.js'
const props=defineProps({source:Object})
const data=ref(props.source||null),error=ref(''),busy=ref(false),range=ref(monthWindow())
let sequence=0
async function changePeriod(value){range.value=value;const run=++sequence;busy.value=true;error.value='';data.value=null;try{const result=await request('commercial','metrics',value);if(run===sequence)data.value=result}catch(e){if(run===sequence)error.value=e.message}finally{if(run===sequence)busy.value=false}}
const monthly=computed(()=>data.value?.monthly_collections||[])
const peak=computed(()=>Math.max(1,...monthly.value.map(x=>Number(x.gross_minor))))
const share=computed(()=>total()?Math.round(total('Bank transfer')/total()*100):0)
const total=channel=>data.value?.collections.filter(x=>!channel||x.payment_channel===channel).reduce((n,x)=>n+Number(x.gross_minor||0),0)||0
const count=channel=>data.value?.collections.filter(x=>x.payment_channel===channel).reduce((n,x)=>n+Number(x.payments||0),0)||0
const hours=computed(()=>data.value?.scheduled_completed_hours.reduce((n,x)=>n+Number(x.hours||0),0).toFixed(1))
const money=n=>'LKR '+new Intl.NumberFormat('en-LK').format(n/100)
onMounted(()=>{if(!props.source)changePeriod(range.value)})
function download(){const rows=[['Class','Teacher','Channel','Payments','Students','Gross LKR'],...data.value.collections.map(r=>{const c=data.value.classrooms.find(c=>c.name===r.classroom);return [c?.title||r.classroom,c?.teacher,r.payment_channel,r.payments,r.students,r.gross_minor/100]})];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv'}));a.download='sisu-class-collections-'+range.value.start_date+'-to-'+range.value.end_date+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
</script>
<template><section class="collection-overview"><PaymentPeriod :busy="busy" @change="changePeriod"/><p class="field-help">Collection dates use the date the verified payment was recorded in SISU.</p><p v-if="error" role="alert" class="error">{{error}}</p><template v-if="data"><div class="collection-panels"><section class="panel provider-revenue-chart"><header><div><span class="eyebrow">A CLEARER PICTURE</span><h2>Verified collections</h2></div><strong>{{money(total())}}<small>{{data.start_date||range.start_date}} — {{data.end_date||range.end_date}}</small></strong></header><div v-if="monthly.length" class="revenue-bars" role="img" aria-label="Verified collections recorded by month"><div v-for="r in monthly" :key="r.month" class="revenue-column"><span class="bar-value">{{money(Number(r.gross_minor))}}</span><div class="bar-track"><span :style="{height:(Number(r.gross_minor)/peak*100)+'%'}"></span></div><small>{{r.month}}</small></div></div><p v-else class="revenue-empty">Your monthly collection history will grow here as payments are verified.</p><p class="field-help">Selected period · verified collections recorded in SISU, not a bank balance.</p></section><section class="panel payment-mix"><span class="eyebrow">HOW STUDENTS PAY</span><h2>Payment channels</h2><div class="payment-mix-body"><div class="payment-ring" :style="{background:total()?'conic-gradient(#51238b '+share+'%, #d9caeb 0)':'#eee9f4'}" role="img" :aria-label="share+' percent of verified collections came from bank transfers'"><div><strong>{{share}}%</strong><small>bank transfer</small></div></div><div class="payment-legend"><p><i></i>Bank transfer<strong>{{money(total('Bank transfer'))}}</strong><small>{{count('Bank transfer')}} payments</small></p><p><i></i>LMS gateway<strong>{{money(total('LMS gateway'))}}</strong><small>{{count('LMS gateway')}} payments</small></p></div></div><p class="field-help">{{data.hours_note}}</p></section></div><details class="panel"><summary>Class & teacher collection report</summary><p>Institute-owned class fees belong to the institute. This breakdown helps the institute arrange teacher compensation.</p><button class="button subtle" @click="download">Download CSV</button><div class="table-wrap"><table><thead><tr><th>Class</th><th>Teacher</th><th>Payment channel</th><th>Payments</th><th>Students</th><th>Gross</th></tr></thead><tbody><tr v-for="r in data.collections"><td>{{data.classrooms.find(c=>c.name===r.classroom)?.title||r.classroom}}</td><td>{{data.classrooms.find(c=>c.name===r.classroom)?.teacher}}</td><td>{{r.payment_channel}}</td><td>{{r.payments}}</td><td>{{r.students}}</td><td>{{money(r.gross_minor)}}</td></tr></tbody></table></div></details></template></section></template>
<style scoped>.collection-panels{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:22px;margin-bottom:24px}.collection-panels>.panel{min-width:0;padding:26px;border-radius:16px;background:#fff}.collection-panels h2{font-size:19px;margin:10px 0 20px;color:#211629}.provider-revenue-chart header{display:flex;justify-content:space-between;gap:16px}.provider-revenue-chart header>strong{font-size:21px;color:#482071;text-align:right}.provider-revenue-chart header small{display:block;font-size:10px;font-weight:400;color:#7e7188;margin-top:6px}.revenue-bars{display:flex;align-items:flex-end;gap:16px;height:185px;margin:20px 0}.revenue-column{flex:1;min-width:0;text-align:center}.bar-track{height:135px;display:flex;align-items:flex-end;border-bottom:1px solid #e9e1f0;margin:8px 0}.bar-track span{width:70%;margin:auto auto 0;min-height:2px;background:linear-gradient(#b897df,#53278b);border-radius:7px 7px 0 0;transition:filter .2s}.bar-track:hover span{filter:brightness(1.18)}.bar-value{font-size:9px;color:#6f587d}.revenue-column>small{font-size:10px;color:#73667f}.payment-mix-body{display:flex;gap:24px;align-items:center;margin:26px 0}.payment-ring{border-radius:50%;width:140px;height:140px;display:grid;place-items:center;flex-shrink:0}.payment-ring>div{width:110px;height:110px;background:#fff;border-radius:50%;display:grid;align-content:center;text-align:center;gap:4px}.payment-ring strong{font-size:26px;color:#4b237d}.payment-ring small{font-size:10px;color:#766682}.payment-legend p{font-size:11px;color:#6f637b;position:relative;padding-left:15px;line-height:1.5}.payment-legend i{position:absolute;left:0;top:5px;background:#51238b;width:7px;height:7px;border-radius:50%}.payment-legend p+p i{background:#d9caeb}.payment-legend strong,.payment-legend small{display:block;margin-top:4px}.payment-legend strong{font-size:15px;color:#2f1d40}.revenue-empty{padding:44px 0;font-size:13px;line-height:1.8;color:#81718c}@media(max-width:1150px){.collection-panels{grid-template-columns:1fr}}@media(max-width:600px){.collection-panels>.panel{padding:20px}.revenue-bars{gap:6px}.bar-value{font-size:8px}.payment-mix-body{gap:18px}.payment-ring{width:115px;height:115px}.payment-ring>div{width:90px;height:90px}.provider-revenue-chart header{flex-wrap:wrap}}.collection-overview{margin-bottom:26px}.collection-overview .provider-metrics strong{font-size:24px}.collection-overview details{margin-bottom:20px}.collection-overview summary{cursor:pointer;font-weight:650}.collection-overview details p{margin:14px 0;line-height:1.7}</style>
